cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt) && echo "=== AWS provider test via autonomous/credentials (AWS SNS verified) + search for S3/CloudFront in full creds ===" && node -e "
const r=require('/tmp/g1_creds.json');
const j=JSON.stringify(r);
// AWS account
const acct=j.match(/account[^\"]*\":?\s*\"?(\d{10,})\"?/i);
if(acct)console.log('awsAccount:',acct[1]);
// S3 bucket
const s3=j.match(/s3[^\"]*bucket[^\"]*\":?\s*\"?([a-z0-9-]+)\"?/i);
if(s3)console.log('s3Bucket:',s3[1]);
// region
const reg=j.match(/region[^\"]*\":?\s*\"?(us-[a-z]+-\d+)\"?/i);
if(reg)console.log('awsRegion:',reg[1]);
console.log('--- all credential services ---');
